-- Fixture estrutural mínima baseada no schema consultado via MCP em 09/10/2026.
-- Somente para PGlite. Não é dump e não contém clientes/usuários de produção.
create role anon;
create role authenticated;
create role service_role bypassrls;
create table usuarios_permitidos(id uuid primary key, role text, ativo boolean);
create table app_unidades(id uuid primary key,chave text,ativo boolean);
create table app_usuarios_unidades(usuario_id uuid,unidade_id uuid);
create table pedidos_personalizados_fornecedores(id uuid primary key,chave text unique,disponivel boolean);
create table sgi_produtos_cache(produto_id_sgi bigint primary key,codigo text unique,descricao text,preco numeric,ativo boolean,fora_linha boolean,ultima_validacao_sgi timestamptz,ultima_alteracao_webhook timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table pedidos_personalizados_produtos(id uuid primary key default gen_random_uuid(),fornecedor_id uuid not null references pedidos_personalizados_fornecedores(id),codigo text not null,descricao text not null,ativo boolean not null default true,ordem integer not null,produto_id_sgi bigint references sgi_produtos_cache(produto_id_sgi) on update cascade on delete restrict,unique(fornecedor_id,codigo),unique(fornecedor_id,ordem));
create unique index pedidos_personalizados_produtos_produto_id_sgi_uidx on pedidos_personalizados_produtos(produto_id_sgi) where produto_id_sgi is not null;
create table pedidos_personalizados_pedidos(id uuid primary key default gen_random_uuid(),fornecedor_id uuid not null references pedidos_personalizados_fornecedores(id),unidade_id uuid not null references app_unidades(id),consultora text not null check(char_length(btrim(consultora)) between 2 and 20),cliente text not null check(char_length(btrim(cliente)) between 1 and 40),telefone_normalizado text check(telefone_normalizado ~ '^[0-9]{10,11}$'),numero_lancamento text check(numero_lancamento ~ '^[0-9]{1,6}$'),data_entrega date,data_pedido_fornecedor date,numero_pedido_compra text,comprador text,status text not null default 'RASCUNHO' check(status in ('RASCUNHO','VENDA FECHADA','AGUARDANDO LAYOUT','AGUARDANDO APROVAÇÃO DO CLIENTE','EM PRODUÇÃO','RECEBIDO','CANCELADO')),version integer not null default 1,created_by uuid not null references usuarios_permitidos(id),updated_by uuid not null references usuarios_permitidos(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),idempotency_key uuid not null,unique(created_by,idempotency_key));
create table pedidos_personalizados_status_historico(id uuid primary key default gen_random_uuid(),pedido_id uuid not null references pedidos_personalizados_pedidos(id),status_anterior text not null,status_novo text not null,usuario_id uuid not null references usuarios_permitidos(id),unidade_id uuid not null references app_unidades(id),version_anterior integer not null,version_nova integer not null,justificativa text,data_recebimento date,created_at timestamptz not null default now());
