-- Fila existente: metadados reais, sem registros de produção.
create table public."pedidos_personalizados_storage_pendencias" ("id" uuid default gen_random_uuid() not null,"bucket_id" text default 'pedidos-personalizados-anexos'::text not null,"caminho_objeto" text not null,"motivo" text not null,"tentativas" integer default 0 not null,"proxima_tentativa_em" timestamp with time zone default now() not null,"ultimo_erro" text,"processado_em" timestamp with time zone,"created_at" timestamp with time zone default now() not null,"updated_at" timestamp with time zone default now() not null);
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_bucket_check" CHECK ((bucket_id = 'pedidos-personalizados-anexos'::text));
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_caminho_check" CHECK ((caminho_objeto ~ '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}/[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}/[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}/[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}\.(jpg|png|webp|pdf)$'::text));
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_motivo_check" CHECK ((motivo = ANY (ARRAY['SUBSTITUICAO'::text, 'REMOCAO_ANEXO'::text, 'REMOCAO_TAPETE'::text, 'REMOCAO_PEDIDO'::text, 'FALHA_APOS_UPLOAD'::text])));
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_pkey" PRIMARY KEY (id);
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_tentativas_check" CHECK ((tentativas >= 0));
alter table public."pedidos_personalizados_storage_pendencias" add constraint "pedidos_personalizados_storage_pendencias_ultimo_erro_check" CHECK (((ultimo_erro IS NULL) OR ((char_length(ultimo_erro) >= 1) AND (char_length(ultimo_erro) <= 500))));
CREATE UNIQUE INDEX idx_pedidos_personalizados_storage_pendencias_objeto_pendente ON public.pedidos_personalizados_storage_pendencias USING btree (bucket_id, caminho_objeto) WHERE (processado_em IS NULL);
CREATE INDEX idx_pedidos_personalizados_storage_pendencias_proxima_tentativa ON public.pedidos_personalizados_storage_pendencias USING btree (proxima_tentativa_em, id) WHERE (processado_em IS NULL);
grant select,insert,update,delete on public.pedidos_personalizados_storage_pendencias to service_role;
